package com.bjjj.todo;
import android.app.*;import android.appwidget.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;
public class WidgetTests extends Instrumentation {
 void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle status=new Bundle();status.putString("id","InstrumentationTestRunner");status.putInt("numtests",1);status.putInt("current",1);status.putString("class",getClass().getName());status.putString("test","persistenceAndNativeWidget");sendStatus(1,status);AppWidgetHost[] host={null};try{Context c=getTargetContext();c.deleteFile("tasks.json");JSONObject draft=new JSONObject().put("title","组件测试：论文图表核对").put("priority","high").put("category","research").put("due",java.time.Instant.now().plusSeconds(7200).toString()).put("offsets",new JSONArray());JSONObject task=Store.save(c,draft);check(Store.open(Store.read(c)).size()==1,"Task persisted");try{Store.save(c,new JSONObject().put("title"," "));throw new AssertionError("Empty title accepted");}catch(IllegalArgumentException ignored){}catch(Exception expected){}Store.done(c,task.getString("id"),true);Store.done(c,task.getString("id"),true);check(Store.open(Store.read(c)).isEmpty(),"Completion must be idempotent");Store.done(c,task.getString("id"),false);
  MainActivity activity=(MainActivity)startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));int[] widgetId={0};AppWidgetHostView[] view={null};runOnMainSync(()->{host[0]=new AppWidgetHost(activity,201);widgetId[0]=host[0].allocateAppWidgetId();AppWidgetManager m=AppWidgetManager.getInstance(activity);Bundle options=new Bundle();options.putInt(AppWidgetManager.OPTION_APPWIDGET_MIN_WIDTH,350);options.putInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,600);check(m.bindAppWidgetIdIfAllowed(widgetId[0],new ComponentName(activity,TodoWidget.class),options),"Widget binding permission");view[0]=host[0].createView(activity,widgetId[0],m.getAppWidgetInfo(widgetId[0]));activity.setContentView(view[0]);host[0].startListening();TodoWidget.updateAll(activity);});
  View[] checkbox={null};for(int attempt=0;attempt<80&&checkbox[0]==null;attempt++){Thread.sleep(250);runOnMainSync(()->checkbox[0]=view[0].findViewById(R.id.check));}check(checkbox[0]!=null,"Native scrolling collection rendered");runOnMainSync(()->checkbox[0].performClick());for(int i=0;i<40&&!Store.open(Store.read(c)).isEmpty();i++)Thread.sleep(150);check(Store.open(Store.read(c)).isEmpty(),"Widget checkbox persisted completion");runOnMainSync(()->{host[0].deleteAppWidgetId(widgetId[0]);host[0].stopListening();activity.finish();});status.putString("stream","\nPassed persistence, validation, idempotent completion and native AppWidget list click.\n");sendStatus(0,status);Bundle result=new Bundle();result.putString("stream","\nOK (1 test)\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){status.putString("stack",android.util.Log.getStackTraceString(e));sendStatus(-2,status);Bundle result=new Bundle();result.putString("stream",android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
}
